const TradingCup = () => {
  const cupWorkerRef = useRef<Worker>();
  const orderFeedWorkerRef = useRef<Worker>();
  const symbol = useSelector((state: AppState) => state.screenerSlice.symbol);
  const [settings, setSettings] = useState<SettingsCup>({
    timeout: "40",
    aggregation: true,
    maxVolume: window.localStorage.getItem(`cup-volume-${symbol}`) || "1000",
    isFixedVolume: null !== window.localStorage.getItem(`cup-volume-${symbol}`),
    minQuantity: window.localStorage.getItem(`order-feed-min-qty-${symbol}`) || "0",
    dollarsVolume: null !== window.localStorage.getItem(`cup-dollars-volume-${symbol}`),
  });
  const [showSettings, setShowSettings] = useState(false);

  useEffect(() => {
    const channel = new MessageChannel();
    cupWorkerRef.current?.postMessage({type: "set_port", port: channel.port1}, [channel.port1]);
    orderFeedWorkerRef.current?.postMessage({type: "set_port", port: channel.port2}, [channel.port2]);
  }, []);

  useEffect(() => {
    setSettings({
      ...settings,
      maxVolume: window.localStorage.getItem(`cup-volume-${symbol}`) || "1000",
      isFixedVolume: null !== window.localStorage.getItem(`cup-volume-${symbol}`),
      minQuantity: window.localStorage.getItem(`order-feed-min-qty-${symbol}`) || "0",
      dollarsVolume: null !== window.localStorage.getItem(`cup-dollars-volume-${symbol}`),
    });
  }, [symbol]);

  return <Stack direction="row" height="100%">

    <div className={styles.Cup}>
      <Cup
        symbol={symbol}
        workerRef={cupWorkerRef}
        settings={settings}
        setShowSettings={setShowSettings}
      />
    </div>

    <SettingsPopupCup
      settings={settings}
      setSettings={setSettings}
      showSettings={showSettings}
      setShowSettings={setShowSettings}
    />
  </Stack>;
};

