Если вы не хотите использовать асинхронное программирование с помощью async/await, вы можете использовать GCD (Grand Central Dispatch) для создания синхронного кода. Вот пример:

```swift
import Foundation

func fetchData1(completion: @escaping (Result<String, Error>) -> Void) {
    // Здесь выполняется первый запрос
    // Обработка успешного выполнения запроса:
    let data1 = "Data from request 1"
    completion(.success(data1))

    // Обработка ошибки:
    // let error = NSError(domain: "com.example", code: 500, userInfo: nil)
    // completion(.failure(error))
}

func fetchData2(completion: @escaping (Result<String, Error>) -> Void) {
    // Здесь выполняется второй запрос
    // Обработка успешного выполнения запроса:
    let data2 = "Data from request 2"
    completion(.success(data2))

    // Обработка ошибки:
    // let error = NSError(domain: "com.example", code: 404, userInfo: nil)
    // completion(.failure(error))
}

func makeRequests() {
    let semaphore = DispatchSemaphore(value: 0)

    var error: Error?

    fetchData1 { result in
        switch result {
        case .success(let data):
            print("Request 1 succeeded: \(data)")
        case .failure(let err):
            error = err
        }
        semaphore.signal()
    }

    fetchData2 { result in
        switch result {
        case .success(let data):
            print("Request 2 succeeded: \(data)")
        case .failure(let err):
            error = err
        }
        semaphore.signal()
    }

    semaphore.wait()

    if let error = error {
        print("Error occurred: \(error)")
        return
    }

    print("Both requests completed successfully")
}

makeRequests()
```

Вы можете заменить заглушки запросов `fetchData1` и `fetchData2` на фактический код ваших запросов. Код использует `DispatchSemaphore` для создания блокировки и дожидания завершения обоих запросов перед продолжением выполнения. Если во время выполнения одного из запросов происходит ошибка, она сохраняется в переменную `error`, а после обработки всех запросов проверяется переменная `error` на наличие ошибки.

Если вы хотите сразу выдавать ошибку, если по какому-то запросу возникла ошибка, вы можете использовать DispatchGroup для ожидания завершения всех запросов и управления показом ошибки. Вот пример:

```swift
import Foundation

func fetchData1(completion: @escaping (Result<String, Error>) -> Void) {
    // Здесь выполняется первый запрос
    // Обработка успешного выполнения запроса:
    let data1 = "Data from request 1"
    completion(.success(data1))

    // Обработка ошибки:
    // let error = NSError(domain: "com.example", code: 500, userInfo: nil)
    // completion(.failure(error))
}

func fetchData2(completion: @escaping (Result<String, Error>) -> Void) {
    // Здесь выполняется второй запрос
    // Обработка успешного выполнения запроса:
    let data2 = "Data from request 2"
    completion(.success(data2))

    // Обработка ошибки:
    // let error = NSError(domain: "com.example", code: 404, userInfo: nil)
    // completion(.failure(error))
}

func makeRequests() {
    let group = DispatchGroup()
    var error: Error?

    group.enter()
    fetchData1 { result in
        defer { group.leave() }
        switch result {
        case .success(let data):
            print("Request 1 succeeded: \(data)")
        case .failure(let err):
            error = err
        }
    }

    group.enter()
    fetchData2 { result in
        defer { group.leave() }
        switch result {
        case .success(let data):
            print("Request 2 succeeded: \(data)")
        case .failure(let err):
            error = err
        }
    }

    group.notify(queue: DispatchQueue.main) {
        if let error = error {
            print("Error occurred: \(error)")
        } else {
            print("Both requests completed successfully")
        }
    }
}

makeRequests()
