Для реализации кучи без использования библиотек vector и стандартной библиотеки шаблонов можно создать класс Heap, который будет хранить данные в виде массива и иметь методы для добавления, поиска и удаления узлов. 

Класс Heap будет иметь следующую структуру:

```cpp
#include <iostream> // для вывода результатов

class Heap {
private:
    int* heap; // массив для хранения узлов кучи
    int size;  // размер кучи
public:
    Heap(); // конструктор по умолчанию
    ~Heap(); // деструктор

    void insert(int value); // добавить узел в кучу
    bool search(int value); // найти узел в куче
    bool remove(int value); // удалить узел из кучи

    void print(); // вывод текущего состояния кучи
};
```

Реализация каждого из методов будет выглядеть следующим образом:

```cpp
Heap::Heap() {
    heap = new int[100]; // создаем массив из 100 элементов
    size = 0; // инициализируем размер кучи
}

Heap::~Heap() {
    delete[] heap; // освобождаем память, выделенную для массива
}

void Heap::insert(int value) {
    int index = size; // индекс нового узла равен текущему размеру кучи
    heap[index] = value; // добавляем новый узел в массив

    size++; // увеличиваем размер кучи

    // выполняем восстановление свойства кучи (например, с помощью просеивания вверх)
    while (index > 0 && heap[(index - 1) / 2] < heap[index]) {
        std::swap(heap[(index - 1) / 2], heap[index]);
        index = (index - 1) / 2;
    }
}

bool Heap::search(int value) {
    for (int i = 0; i < size; i++) {
        if (heap[i] == value) {
            return true; // значение найдено в куче
        }
    }

    return false; // значение не найдено
}

bool Heap::remove(int value) {
    for (int i = 0; i < size; i++) {
        if (heap[i] == value) {
            // перемещаем последний узел вместо удаляемого
            heap[i] = heap[size - 1];

            size--; // уменьшаем размер кучи

            // выполняем восстановление свойства кучи (например, с помощью просеивания вниз)
            while (true) {
                int left = 2 * i + 1;
                int right = 2 * i + 2;

                int largest = i;

                if (left < size && heap[left] > heap[largest]) {
                    largest = left;
                }

                if (right < size && heap[right] > heap[largest]) {
                    largest = right;
                }

                if (largest != i) {
                    std::swap(heap[i], heap[largest]);
                    i = largest;
                } else {
                    break;
                }
            }

            return true; // узел удален из кучи
        }
    }

    return false; // узел не найден
}

void Heap::print() {
    for (int i = 0; i < size; i++) {
        std::cout << heap[i] << " ";
    }

    std::cout << std::endl;
}

int main() {
    Heap heap;

    heap.insert(6);
    heap.insert(4);
    heap.insert(9);
    heap.insert(2);

    heap.print(); // выводит: 9 4 6 2

    std::cout << heap.search(4) << std::endl; // выводит: 1 (значение 4 найдено)
    std::cout << heap.search(8) << std::endl; // выводит: 0 (значение 8 не найдено)

    std::cout << heap.remove(4) << std::endl; // выводит: 1 (узел 4 удален)
    std::cout << heap.remove(8) << std::endl; // выводит: 0 (узел 8 не найден)

    heap.print(); // выводит: 9 2 6

    return 0;
}
```

