```java
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.util.math.MatrixStack;
import net.minecraft.util.Identifier;
import org.lwjgl.opengl.GL11;

public class MyScreen extends Screen {

    private float rotation;
    private Identifier texture;

    public MyScreen() {
        super();
        rotation = 0.0f;
        texture = new Identifier("modid", "textures/cube.png");
    }

    @Override
    public void render(MatrixStack matrices, int mouseX, int mouseY, float delta) {
        // 清除屏幕
        clearScreen();

        // 更新旋转角度
        rotation += delta * 0.5f;
        if (rotation >= 360.0f) {
            rotation -= 360.0f;
        }

        // 设置透视投影矩阵
        setupPerspective();

        // 绘制旋转的正方体
        drawRotatingCube(matrices, delta);
    }

    private void clearScreen() {
        renderBackground();
    }

    private void setupPerspective() {
        float aspectRatio = (float) width / (float) height;
        GL11.glMatrixMode(GL11.GL_PROJECTION);
        GL11.glLoadIdentity();
        GL11.glFrustum(-aspectRatio, aspectRatio, -1.0f, 1.0f, 1.0f, 1000.0f);
        GL11.glMatrixMode(GL11.GL_MODELVIEW);
        GL11.glLoadIdentity();
    }

    private void drawRotatingCube(MatrixStack matrices, float delta) {
        // 开始渲染
        GL11.glPushMatrix();
        GL11.glTranslatef(width / 2.0f, height / 2.0f, -500.0f); // 设置旋转中心和深度
        GL11.glRotatef(rotation, 1.0f, 1.0f, 1.0f); // 绕 xyz 轴旋转

        // 绘制正方体
        bindTexture(texture);
        renderCube(matrices);

        // 结束渲染
        GL11.glPopMatrix();
    }

    private void renderCube(MatrixStack matrices) {
        // 绘制正方体的六个面
        // 根据顶点坐标和纹理坐标绘制
        // ...
    }

}
```

在这个示例代码中，`MyScreen` 是自定义的 `Screen` 类，其中 `rotation` 变量记录旋转的角度，`texture` 变量引用了正方体的纹理资源。

在 `render()` 方法中，我们先清除屏幕，然后更新旋转角度，接着设置透视投影矩阵，最后调用 `drawRotatingCube()` 方法绘制旋转的正方体。

在 `drawRotatingCube()` 方法中，我们使用 `GL11.glPushMatrix()` 和 `GL11.glPopMatrix()` 来将渲染状态与旋转的正方体分开。我们调用 `GL11.glTranslatef()` 来设置旋转中心点位置和深度，然后调用 `GL11.glRotatef()` 绕 xyz 轴旋转。

最后，我们绑定了正方体的纹理并调用 `renderCube()` 方法来绘制正方体的六个面。你需要根据实际需求绘制正方体的顶点和纹理坐标。

