    Mat A;
    MatCreate(comm, &A);
    MatSetSizes(A, PETSC_DECIDE, PETSC_DECIDE, m, n);
    MatSetType(A, MATMPIAIJ);
    MatSetUp(A);

    // Создание вектора b
    Vec b;
    VecCreate(comm, &b);
    VecSetSizes(b, PETSC_DECIDE, n);
    VecSetFromOptions(b);

    // Создание вектора c равного произведению A и b
    Vec c;
    VecDuplicate(b, &c);
    MatMult(A, b, c);

    // Вывод вектора c
    VecView(c, PETSC_VIEWER_STDOUT_WORLD);

    // Освобождение памяти
    MatDestroy(&A);
    VecDestroy(&b);
    VecDestroy(&c);

    // Завершение работы с PETSc
    PetscFinalize();

    return 0;
}
```

