Per aggiungere frecce all'indicatore esistente, dobbiamo prima stabilire in quali condizioni queste frecce dovrebbero essere mostrate. Tipicamente, le frecce stocastiche sono mostrate quando il %K incrocia il %D da sopra a sotto per una freccia verso il basso (vendita) e da sotto a sopra per una freccia verso l'alto (acquisto). Il seguente esempio di codice implementa questa logica nella funzione `start()`:

```mql4
int start()
{
    int counted_bars = IndicatorCounted();
    if(counted_bars < 0) return(-1);
    if(counted_bars > 0) counted_bars--;

    int limit = Bars - counted_bars;

    for(int i = limit; i >= 0; i--)
    {
        double currentK = iStochastic(NULL, TimeFrame, KPeriod, DPeriod, Slowing, MAMethod, PriceField, MODE_MAIN, i);
        double currentD = iStochastic(NULL, TimeFrame, KPeriod, DPeriod, Slowing, MAMethod, PriceField, MODE_SIGNAL, i);

        // Per evitare valori di buffer non validi nei calcoli successivi
        if(i == 0 || i == 1)
        {
            BufferK_Curr[i] = currentK;
            BufferD_Curr[i] = currentD;
            continue;
        }

        // Salva i valori precendenti per confronto
        double previousK = BufferK_Curr[i + 1];
        double previousD = BufferD_Curr[i + 1];

        // Popolare il buffer
        BufferK[i] = currentK;
        BufferD[i] = currentD;

        // Questo è per la barra attuale (0) e la barra appena chiusa (1)
        BufferK_Curr[i] = currentK;
        BufferD_Curr[i] = currentD;

        // Incrocio dal basso verso l'alto (%K incrocia %D verso l'alto)
        if(currentK > currentD && previousK <= previousD)
        {
            ArrowUpBuffer[i] = Low[i] - (4 * Point);
        }
        // Incrocio dall'alto verso il basso (%K incrocia %D verso il basso)
        else if(currentK < currentD && previousK >= previousD)
        {
            ArrowDownBuffer[i] = High[i] + (4 * Point);
        }
        // Se non c'è un incrocio, assicurarsi che il buffer delle frecce sia EMPTY_VALUE
        else
        {
            ArrowUpBuffer[i] = EMPTY_VALUE;
            ArrowDownBuffer[i] = EMPTY_VALUE;
        }
    }

    return(0);
}
```

