int start()
{
    // Variabile per conteggiare il numero di barre già calcolate
    int counted_bars = IndicatorCounted();
    // Se c'è un errore, esce
    if(counted_bars < 0) return(-1);
    // Riduce il numero di barre per il calcolo se è stata aggiunta una nuova barra
    if(counted_bars > 0) counted_bars--;
    int limit = Bars - counted_bars;

    // Ciclo attraverso le barre non conteggiate
    for(int i = limit; i >= 0; i--)
    {
        BufferK[i] = iStochastic(NULL, TimeFrame, KPeriod, DPeriod, Slowing, MAMethod, PriceField, MODE_MAIN, i);
        BufferD[i] = iStochastic(NULL, TimeFrame, KPeriod, DPeriod, Slowing, MAMethod, PriceField, MODE_SIGNAL, i);

        // Per evitare l'accesso a valori non esistenti ad i-1 quando i è 0
        if(i == 0) continue;

        // Regola per le frecce verso l’alto
        if(BufferK[i] > BufferD[i] && BufferK[i-1] <= BufferD[i-1])
        {
            ArrowUpBuffer[i] = Low[i] - (4 * Point); // Valori di esempio, regolare se necessario
            ArrowDownBuffer[i] = EMPTY_VALUE; // Assicurarsi di svuotare il buffer delle frecce verso il basso
        }
        // Regola per le frecce verso il basso
        else if(BufferK[i] < BufferD[i] && BufferK[i-1] >= BufferD[i-1])
        {
            ArrowDownBuffer[i] = High[i] + (4 * Point); // Valori di esempio, regolare se necessario
            ArrowUpBuffer[i] = EMPTY_VALUE; // Assicurarsi di svuotare il buffer delle frecce verso l'alto
        }
        else
        {
            // Se non c'è incrocio, svuotiamo i buffer delle frecce
            ArrowUpBuffer[i] = EMPTY_VALUE;
            ArrowDownBuffer[i] = EMPTY_VALUE;
        }
    }

    return(0);
}
