            ArrowUpBuffer[i] = Low[i] - (4 * Point); // Imposta qui il valore in base allo spazio desiderato tra la freccia e il prezzo
            ArrowDownBuffer[i] = EMPTY_VALUE;
        }
        // Incrocio dall’alto verso il basso
        else if(previousK > previousD && currentK < currentD) {
            ArrowDownBuffer[i] = High[i] + (4 * Point); // Imposta qui il valore in base allo spazio desiderato tra la freccia e il prezzo
            ArrowUpBuffer[i] = EMPTY_VALUE;
        }
        else {
            ArrowUpBuffer[i] = EMPTY_VALUE;
            ArrowDownBuffer[i] = EMPTY_VALUE;
        }
    }

    return(0);
